void mergeSort(vector<int>& a, int l, int r, vector<int>& buf) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(a, l, m, buf);
    mergeSort(a, m + 1, r, buf);
    int i = l, j = m + 1, k = l;
    while (i <= m && j <= r)
        buf[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i <= m) buf[k++] = a[i++];
    while (j <= r) buf[k++] = a[j++];
    for (int t = l; t <= r; ++t) a[t] = buf[t];
}

def merge_sort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left = merge_sort(a[:mid])
    right = merge_sort(a[mid:])
    res, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            res.append(left[i]); i += 1
        else:
            res.append(right[j]); j += 1
    res.extend(left[i:])
    res.extend(right[j:])
    return res

class Solution {
    void msort(vector<int>& a, int l, int r, vector<int>& tmp) {
        if (r - l <= 1) return;
        int m = (l + r) / 2;
        msort(a, l, m, tmp); msort(a, m, r, tmp);
        int i = l, j = m, k = l;
        while (i < m && j < r) tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
        while (i < m) tmp[k++] = a[i++];
        while (j < r) tmp[k++] = a[j++];
        for (int t = l; t < r; t++) a[t] = tmp[t];
    }
public:
    vector<int> sortArray(vector<int>& a) {
        vector<int> tmp(a.size());
        msort(a, 0, a.size(), tmp);
        return a;
    }
};

class Solution:
    def sortArray(self, a: list[int]) -> list[int]:
        def msort(arr):
            if len(arr) <= 1:
                return arr
            mid = len(arr) // 2
            left, right = msort(arr[:mid]), msort(arr[mid:])
            res, i, j = [], 0, 0
            while i < len(left) and j < len(right):
                if left[i] <= right[j]:
                    res.append(left[i]); i += 1
                else:
                    res.append(right[j]); j += 1
            res.extend(left[i:]); res.extend(right[j:])
            return res
        return msort(a)

class Solution {
    vector<int> cnt, idx, tmp;
    void msort(vector<int>& a, int l, int r) {
        if (r - l <= 1) return;
        int m = (l + r) / 2;
        msort(a, l, m); msort(a, m, r);
        int i = l, j = m, k = l, right = 0;
        while (i < m && j < r) {
            if (a[idx[j]] < a[idx[i]]) { right++; tmp[k++] = idx[j++]; }
            else { cnt[idx[i]] += right; tmp[k++] = idx[i++]; }
        }
        while (i < m) { cnt[idx[i]] += right; tmp[k++] = idx[i++]; }
        while (j < r) tmp[k++] = idx[j++];
        for (int t = l; t < r; t++) idx[t] = tmp[t];
    }
public:
    vector<int> countSmaller(vector<int>& a) {
        int n = a.size();
        cnt.assign(n, 0); idx.resize(n); tmp.resize(n);
        for (int i = 0; i < n; i++) idx[i] = i;
        msort(a, 0, n);
        return cnt;
    }
};

class Solution:
    def countSmaller(self, a: list[int]) -> list[int]:
        n = len(a)
        cnt = [0] * n
        idx = list(range(n))
        def msort(l, r):
            if r - l <= 1:
                return
            m = (l + r) // 2
            msort(l, m); msort(m, r)
            merged, i, j, right = [], l, m, 0
            while i < m and j < r:
                if a[idx[j]] < a[idx[i]]:
                    right += 1; merged.append(idx[j]); j += 1
                else:
                    cnt[idx[i]] += right; merged.append(idx[i]); i += 1
            while i < m:
                cnt[idx[i]] += right; merged.append(idx[i]); i += 1
            while j < r:
                merged.append(idx[j]); j += 1
            idx[l:r] = merged
        msort(0, n)
        return cnt

class Solution {
    vector<int> tmp;
    long long msort(vector<int>& a, int l, int r) {
        if (r - l <= 1) return 0;
        int m = (l + r) / 2;
        long long c = msort(a, l, m) + msort(a, m, r);
        int j = m;
        for (int i = l; i < m; i++) { while (j < r && a[i] > 2LL * a[j]) j++; c += j - m; }
        int x = l, y = m, k = l;
        while (x < m && y < r) tmp[k++] = (a[x] <= a[y]) ? a[x++] : a[y++];
        while (x < m) tmp[k++] = a[x++];
        while (y < r) tmp[k++] = a[y++];
        for (int t = l; t < r; t++) a[t] = tmp[t];
        return c;
    }
public:
    int reversePairs(vector<int>& a) {
        tmp.resize(a.size());
        return (int)msort(a, 0, a.size());
    }
};

class Solution:
    def reversePairs(self, a: list[int]) -> int:
        def msort(l, r):
            if r - l <= 1:
                return 0
            m = (l + r) // 2
            c = msort(l, m) + msort(m, r)
            j = m
            for i in range(l, m):
                while j < r and a[i] > 2 * a[j]:
                    j += 1
                c += j - m
            a[l:r] = sorted(a[l:r])
            return c
        return msort(0, len(a))

class Solution {
    ListNode* merge2(ListNode* a, ListNode* b) {
        ListNode dummy, *t = &dummy;
        while (a && b) { if (a->val <= b->val) { t->next = a; a = a->next; } else { t->next = b; b = b->next; } t = t->next; }
        t->next = a ? a : b;
        return dummy.next;
    }
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        if (lists.empty()) return nullptr;
        int n = lists.size();
        while (n > 1) {
            int k = (n + 1) / 2;
            for (int i = 0; i < n / 2; i++) lists[i] = merge2(lists[i], lists[i + k]);
            n = k;
        }
        return lists[0];
    }
};

class Solution:
    def mergeKLists(self, lists):
        def merge2(a, b):
            dummy = tail = ListNode()
            while a and b:
                if a.val <= b.val:
                    tail.next, a = a, a.next
                else:
                    tail.next, b = b, b.next
                tail = tail.next
            tail.next = a or b
            return dummy.next
        if not lists:
            return None
        while len(lists) > 1:
            merged = []
            for i in range(0, len(lists), 2):
                a = lists[i]
                b = lists[i + 1] if i + 1 < len(lists) else None
                merged.append(merge2(a, b))
            lists = merged
        return lists[0]

class Solution {
    ListNode* merge2(ListNode* a, ListNode* b) {
        ListNode dummy, *t = &dummy;
        while (a && b) { if (a->val <= b->val) { t->next = a; a = a->next; } else { t->next = b; b = b->next; } t = t->next; }
        t->next = a ? a : b;
        return dummy.next;
    }
public:
    ListNode* sortList(ListNode* head) {
        if (!head || !head->next) return head;
        ListNode *slow = head, *fast = head->next;
        while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }
        ListNode* mid = slow->next; slow->next = nullptr;
        return merge2(sortList(head), sortList(mid));
    }
};

class Solution:
    def sortList(self, head):
        if not head or not head.next:
            return head
        slow, fast = head, head.next
        while fast and fast.next:
            slow, fast = slow.next, fast.next.next
        mid, slow.next = slow.next, None
        left, right = self.sortList(head), self.sortList(mid)
        dummy = tail = ListNode()
        while left and right:
            if left.val <= right.val:
                tail.next, left = left, left.next
            else:
                tail.next, right = right, right.next
            tail = tail.next
        tail.next = left or right
        return dummy.next
